## Headless verification script.  Loads `res://scenes/Animator.tscn`,
## drives the returned tween deterministically with `custom_step(0.01)`
## and checks the Target node state / signal counts at every
## checkpoint from the specification table.

const ANIMATOR_SCENE := "res://scenes/Animator.tscn"
const DT := 0.01

var a_count: int = 0
var b_count: int = 0
var c_count: int = 0
var done_count: int = 0
var errors: Array[String] = []


func _initialize() -> void:
	print("=== tween_chain_sequence_animation verifier ===")

	var packed: PackedScene = load(ANIMATOR_SCENE)
	if packed == null:
		_finish("Failed to load scene %s" % ANIMATOR_SCENE)
		return
	var root: Node = packed.instantiate()
	get_root().add_child(root)

	var controller: Node = root.get_node("TweenController")
	var target: Node2D = root.get_node("Target")

	# Verify initial state.
	if not _approx_eq_pos(target.position, Vector2.ZERO):
		errors.append("Initial position is not (0,0)")
	if not _approx_eq(target.rotation, 0.0):
		errors.append("Initial rotation is not 0")
	if not _approx_eq_pos(target.scale, Vector2.ONE):
		errors.append("Initial scale is not (1,1)")
	if not _approx_eq(target.modulate.a, 1.0):
		errors.append("Initial modulate.a is not 1")

	controller.step_a_complete.connect(func() -> void: a_count += 1)
	controller.step_b_complete.connect(func() -> void: b_count += 1)
	controller.step_c_complete.connect(func() -> void: c_count += 1)
	controller.animation_complete.connect(func() -> void: done_count += 1)

	var tween: Tween = controller.play_sequence()
	if tween == null:
		_finish("play_sequence() returned null")
		return

	# The verifier pauses the returned tween and steps it manually
	# so timing is deterministic.
	tween.pause()

	# Drive the tween through each checkpoint.
	# Step in 10ms increments up to 3.5 s.  We accumulate simulated
	# time to know which checkpoint to assert.
	var sim_time: float = 0.0
	var total: float = 3.5
	var checkpoints: Dictionary = {
		0.5:  _make_checkpoint(0, 0, 0, 0, "t=0.50"),
		1.0:  _make_checkpoint(1, 0, 0, 0, "t=1.00"),
		1.5:  _make_checkpoint(1, 0, 0, 0, "t=1.50"),
		2.0:  _make_checkpoint(1, 1, 0, 0, "t=2.00"),
		3.0:  _make_checkpoint(1, 1, 1, 0, "t=3.00"),
		3.5:  _make_checkpoint(1, 1, 1, 1, "t=3.50"),
	}

	while sim_time < total + DT * 0.5:
		tween.custom_step(DT)
		sim_time += DT
		var key: String = "%.2f" % sim_time
		if checkpoints.has(key):
			var cp: Dictionary = checkpoints[key]
			_assert_checkpoint(cp, target, controller, sim_time)

	# Final state check
	if not controller.is_running() == false:
		errors.append("is_running() should be false after 3.5s, got %s" % str(controller.is_running()))
	if not _approx_eq_pos(target.position, Vector2(200, 100)):
		errors.append("Final position should be (200,100), got %s" % str(target.position))
	if not _approx_eq(target.rotation, PI / 2.0):
		errors.append("Final rotation should be PI/2, got %f" % target.rotation)
	if not _approx_eq_pos(target.scale, Vector2(2, 2)):
		errors.append("Final scale should be (2,2), got %s" % str(target.scale))
	if not _approx_eq(target.modulate.r, 0.5):
		errors.append("Final modulate.r should be 0.5, got %f" % target.modulate.r)
	if not _approx_eq(target.modulate.a, 1.0):
		errors.append("Final modulate.a should be 1.0, got %f" % target.modulate.a)

	if errors.is_empty():
		print("ALL CHECKS PASSED")
		_finish("ok")
	else:
		for e in errors:
			print("FAIL: ", e)
		_finish("FAIL")


func _make_checkpoint(a: int, b: int, c: int, d: int, label: String) -> Dictionary:
	return {"a": a, "b": b, "c": c, "d": d, "label": label}


func _assert_checkpoint(cp: Dictionary, target: Node2D, controller: Node, t: float) -> void:
	var label: String = cp.label
	if a_count != cp.a:
		errors.append("%s: step_a_complete count expected %d, got %d" % [label, cp.a, a_count])
	if b_count != cp.b:
		errors.append("%s: step_b_complete count expected %d, got %d" % [label, cp.b, b_count])
	if c_count != cp.c:
		errors.append("%s: step_c_complete count expected %d, got %d" % [label, cp.c, c_count])
	if done_count != cp.d:
		errors.append("%s: animation_complete count expected %d, got %d" % [label, cp.d, done_count])
	# Note: we do not over-assert state at every checkpoint as the task
	# only requires signal counts, endpoints and intermediate samples.


func _approx_eq(a: float, b: float, tol: float = 0.05) -> bool:
	return absf(a - b) <= tol


func _approx_eq_pos(a: Vector2, b: Vector2, tol: float = 0.05) -> bool:
	return absf(a.x - b.x) <= tol and absf(a.y - b.y) <= tol


func _finish(msg: String) -> void:
	print("Result: ", msg)
	quit(0 if msg == "ok" else 1)

